
-- Fixed licensed form content is frozen independently from tenant activation.
-- This catalogue records implementation identity; it does not fabricate rule approval.

create table private.questionnaire_form_catalog (
  form_key text not null,
  form_version text not null,
  form_snapshot jsonb not null,
  rule_snapshot jsonb not null,
  catalog_hash text not null check (catalog_hash ~ '^[a-f0-9]{64}$'),
  primary key(form_key,form_version)
);
alter table private.questionnaire_form_catalog enable row level security;
alter table private.questionnaire_form_catalog force row level security;
revoke all on private.questionnaire_form_catalog from public,anon,authenticated,service_role;
create trigger questionnaire_form_catalog_append_only before update or delete on private.questionnaire_form_catalog
for each row execute function private.questionnaire_assessment_append_only();

insert into private.questionnaire_form_catalog(form_key,form_version,form_snapshot,rule_snapshot,catalog_hash)
select item->>'formKey',item->>'formVersion',item->'formSnapshot',item->'ruleSnapshot',
  encode(sha256(convert_to((item->'formSnapshot')::text||':'||(item->'ruleSnapshot')::text,'UTF8')),'hex')
